def init_vertexai_client(project_id: str, location: str):
    if not project_id:
        project_id = os.environ.get("GCP_PROJECT_ID")
    if not location:
        location = os.environ.get("GCP_LOCATION")

    if not project_id or not location:
        raise ValueError("GCP_PROJECT_ID and GCP_LOCATION must be provided or set as environment variables.")

