  "platform_output_safety.py": "from typing import Dict, Any
from vertexai.generative_models import GenerationResponse
from model_models import ModelInvocationResponse, SafetyCheckResult

def check_output_safety(model_invocation_response: ModelInvocationResponse) -> SafetyCheckResult:
    raw_response: GenerationResponse = model_invocation_response.raw_response

    is_safe = True
    safety_attributes: Dict[str, Any] = {}

    if raw_response.candidates:
        candidate = raw_response.candidates[0]
        if hasattr(candidate, 'safety_ratings'): # Older structure
            safety_attributes["safety_ratings"] = [rating.to_dict() for rating in candidate.safety_ratings]
            for rating in candidate.safety_ratings:
                if rating.blocked: # Check if any category is blocked
                    is_safe = False
                    break
        elif hasattr(candidate, 'safety_attributes'): # Newer structure, if available
            # This path is less common for direct blocking, but good to collect attributes
            safety_attributes["safety_attributes"] = candidate.safety_attributes.to_dict()
            # Vertex AI typically uses finish_reason 'SAFETY' or blocks a candidate if unsafe
            if candidate.finish_reason.name == 'SAFETY':
                is_safe = False

    # If no candidate or safety issues prevent a candidate, it's generally considered safe to return content
    # If the response itself indicates issues (e.g., prompt filtered), is_safe might be False
    if not raw_response.candidates and raw_response.prompt_feedback and raw_response.prompt_feedback.block_reason:
        is_safe = False
        safety_attributes["prompt_feedback"] = raw_response.prompt_feedback.to_dict()

    return SafetyCheckResult(is_safe=is_safe, safety_attributes=safety_attributes)",
