from google.cloud import translate_v3 as translate
from model_models import TranslatedOutput

def localized_platform_output(text: str, target_language_code: str, project_id: str = None, location: str = 'global') -> TranslatedOutput:
    project_id = os.environ.get("GCP_PROJECT_ID", project_id)
    if not project_id:
        raise ValueError("GCP_PROJECT_ID must be provided or set as an environment variable.")

    client = translate.TranslationServiceClient()

    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language_code,
        }
    )

    translated_text = response.translations[0].translated_text if response.translations else ""

    return TranslatedOutput(
        original_text=text,
        translated_text=translated_text,
        target_language=target_language_code
    )",
